CREATE EXTENSION IF NOT EXISTS btree_gist;
ALTER TABLE service_requests ADD COLUMN IF NOT EXISTS symptoms jsonb NOT NULL DEFAULT '{}';
CREATE TABLE IF NOT EXISTS upload_references (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL REFERENCES users(id), file_name text NOT NULL, content_type text NOT NULL, size_bytes integer NOT NULL CHECK (size_bytes > 0 AND size_bytes <= 25000000), storage_key text, status text NOT NULL CHECK (status IN ('initiated','quarantined','ready','rejected')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS booking_holds (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_id uuid NOT NULL REFERENCES users(id), mechanic_id uuid REFERENCES users(id), starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, expires_at timestamptz NOT NULL, status text NOT NULL CHECK (status IN ('active','expired','converted','cancelled')), idempotency_key text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), CHECK (ends_at > starts_at));
ALTER TABLE appointments ADD COLUMN IF NOT EXISTS hold_id uuid REFERENCES booking_holds(id);
ALTER TABLE appointments ADD COLUMN IF NOT EXISTS idempotency_key text;
ALTER TABLE appointments ADD CONSTRAINT appointments_no_overlap EXCLUDE USING gist (mechanic_id WITH =, tstzrange(starts_at, ends_at, '[)') WITH &&) WHERE (status IN ('held','confirmed','scheduled'));
CREATE TABLE IF NOT EXISTS payment_attempts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), invoice_id uuid, customer_id uuid NOT NULL REFERENCES users(id), provider text NOT NULL, provider_reference text, amount_minor bigint NOT NULL CHECK (amount_minor >= 0), currency char(3) NOT NULL, status text NOT NULL CHECK (status IN ('created','pending','succeeded','failed','refunded')), idempotency_key text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS payment_webhook_events (provider text NOT NULL, event_id text NOT NULL, payload jsonb NOT NULL, received_at timestamptz NOT NULL DEFAULT now(), processed_at timestamptz, PRIMARY KEY (provider, event_id));
CREATE UNIQUE INDEX IF NOT EXISTS booking_holds_customer_idempotency ON booking_holds(customer_id, idempotency_key);
CREATE UNIQUE INDEX IF NOT EXISTS payment_attempts_customer_idempotency ON payment_attempts(customer_id, idempotency_key);
